+        } else {
+            destroyApmServices();
+        }
+    }
+
+    void setIncludeNames(List<String> includeNames) {
+        this.includeNames = includeNames;
+        this.filterAutomaton = buildAutomaton(includeNames, excludeNames);
+    }
+
+    void setExcludeNames(List<String> excludeNames) {
