+        spans.computeIfAbsent(spanId, _spanId -> AccessController.doPrivileged((PrivilegedAction<Context>) () -> {
+            logger.trace("Tracing [{}] [{}]", spanId, spanName);
+            final SpanBuilder spanBuilder = services.tracer.spanBuilder(spanName);
